#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024          /* 0x400 bytes – the original limit */

int main(int argc, char **argv)
{
    /* -------------------------------------------------------------
       Usage handling – the original program prints "USAGE" only when
       fewer than two arguments are supplied (argc < 3).  Extra arguments
       are simply ignored.
       ------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* -------------------------------------------------------------
       Length check – if either string is 1025 characters or longer
       the program prints "TOO_LONG".  The original used the constant
       0x401 as the limit.
       ------------------------------------------------------------- */
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }

    /* -------------------------------------------------------------
       Build frequency tables for the two strings.
       * Spaces are ignored.
       * Upper‑case letters are treated case‑insensitively (converted
         to lower‑case); all other bytes are counted unchanged.
       ------------------------------------------------------------- */
    int freq1[256] = {0};
    int freq2[256] = {0};

    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ')
            continue;                     /* ignore spaces */
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + ('a' - 'A'));   /* to lower case */
        ++freq1[c];
    }

    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ')
            continue;                     /* ignore spaces */
        if (c >= 'A' && c <= 'Z')
            c = (unsigned char)(c + ('a' - 'A'));   /* to lower case */
        ++freq2[c];
    }

    /* -------------------------------------------------------------
       Compare the two tables.
       ------------------------------------------------------------- */
    int is_anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (freq1[i] != freq2[i]) {
            is_anagram = 0;
            break;
        }
    }

    puts(is_anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
